def orgs_of_type(type_, orgs=None):
    orgs = load_organisations() if orgs is None else orgs
    return [o for o in orgs if o.get("type") == type_]


def org_chain(org_id, orgs=None):
    """Le nœud, puis ses parents jusqu'à la racine. [] si l'identifiant est inconnu.

    Le garde-fou contre les cycles n'est pas décoratif : un parentId saisi de
    travers ferait tourner cette boucle indéfiniment, et elle sera appelée à
    chaque requête une fois l'étape 2 en service.
    """
    orgs = load_organisations() if orgs is None else orgs
    par_id = {o["id"]: o for o in orgs}
    chaine, vus, courant = [], set(), org_id
    while courant is not None and courant in par_id and courant not in vus:
        vus.add(courant)
        noeud = par_id[courant]
        chaine.append(noeud)
        courant = noeud.get("parentId")
    return chaine


# ── L'IA, autorisée ou non, centre par centre ────────────────────────────────
# Une direction peut refuser que ses élèves parlent à un assistant. Le refus se
# pose sur un nœud de l'arbre et descend : « interdite » sur un CSS ferme ses
# douze centres d'un geste, et celui qui a négocié une exception la porte
# écrite sur lui-même. Rien n'est décidé dans la page de l'élève — les routes
# refusent, sinon ce ne serait pas une décision mais des boutons cachés.
IA_ETATS = ("herite", "autorisee", "interdite")


def ia_effective(org_id, orgs=None):
    """Dit si l'IA est autorisée sur ce nœud. Rend (autorisée, nœud décideur).

    On remonte vers la racine et le PREMIER réglage explicite tranche. Faute
    de réglage nulle part, l'IA reste autorisée : c'est l'état d'avant ce
    champ, et une mise en service ne doit rien éteindre au passage.
    """
    for noeud in org_chain(org_id, orgs):
        if noeud.get("ia") in ("autorisee", "interdite"):
            return noeud["ia"] == "autorisee", noeud
    return True, None


def centre_de_eleve(student, groups=None):
    """Le centre auquel l'élève est rattaché, par son groupe. None si aucun."""
    if not student:
        return None
    groups = load_groups() if groups is None else groups
    groupe = next((g for g in groups if g.get("id") == student.get("groupId")), None)
    return (groupe or {}).get("centreId")


IA_VALEURS = ("herite", "autorisee", "interdite")


def groupe_de_eleve(student, groups=None):
    """Le groupe de l'élève, ou None."""
    if not student:
        return None
    groups = load_groups() if groups is None else groups
    return next((g for g in groups if g.get("id") == student.get("groupId")), None)


def ia_pour_enseignant(teacher, orgs=None, acces=None):
    """(autorisée, décideur) pour un enseignant.

    **Le plus précis gagne**, comme sur l'arbre : le drapeau posé sur la
    personne tranche avant tout, puis on remonte les nœuds. C'est la règle
    déjà écrite pour les organisations — « celui qui a négocié une exception
    la porte écrite sur lui-même » — et en avoir une seconde ici obligerait à
    expliquer, devant chaque bouton grisé, laquelle des deux s'applique.

    Le décideur rendu porte un `type` : l'écran doit pouvoir dire *qui* a
    décidé, et « hérité de CSS X » ne se lit pas comme « réglé sur cette
    personne ».
    """
    if not teacher:
        return True, None
    if teacher.get("ia") in ("autorisee", "interdite"):
        return teacher["ia"] == "autorisee", {
            "type": "enseignant", "id": teacher.get("id"),
            "nom": teacher.get("nom", ""),
        }
    org_id = centre_de_enseignant(teacher, acces=acces)
    if org_id is None:
        racine = orgs_of_type("reseau", orgs)
        org_id = racine[0]["id"] if racine else None
    if org_id is None:
        return True, None
    autorisee, noeud = ia_effective(org_id, orgs)
    return autorisee, (dict(noeud, type=noeud.get("type")) if noeud else None)


def centre_de_enseignant(teacher, acces=None, groups=None):
    """Le centre d'un enseignant : son rattachement, sinon celui de ses groupes.

    Deux sources, et elles ne se recouvrent pas — c'est la leçon déjà payée
    par la vue d'un centre : le fondateur enseigne sans être rattaché, et un
    rattachement retiré laisse ses groupes en place. Lire une seule des deux
    ferait disparaître des personnes de l'écran pendant que leurs élèves
    continuent d'appeler les modèles.
    """
    if not teacher:
        return None
    for a in (load_acces() if acces is None else acces):
        if a.get("teacherId") == teacher.get("id") and a.get("actif", True):
            org = find_org(a.get("orgId"))
            if org is not None and org.get("type") == "centre":
                return org["id"]
    for g in (load_groups() if groups is None else groups):
        if g.get("teacherId") == teacher.get("id") and g.get("centreId"):
            return g["centreId"]
    return None


def ia_pour_eleve(student):
    """(autorisée, décideur) pour un élève donné.

    L'ordre est celui de la précision : le titulaire de son groupe d'abord,
    puis l'arbre. Un groupe pas encore rattaché à un centre retombe sur le
    réglage du réseau — un rattachement oublié ne doit pas devenir une porte
    ouverte.
    """
    groupe = groupe_de_eleve(student)
    if groupe and groupe.get("teacherId"):
        titulaire = next((t for t in load_teachers()
                          if t.get("id") == groupe["teacherId"]), None)
        if titulaire and titulaire.get("ia") in ("autorisee", "interdite"):
            return ia_pour_enseignant(titulaire)
    centre = (groupe or {}).get("centreId")
    if centre is not None:
        return ia_effective(centre)
    racine = orgs_of_type("reseau")
    return ia_effective(racine[0]["id"]) if racine else (True, None)


def org_subtree_ids(org_id, orgs=None):
    """Les identifiants du nœud et de toute sa descendance."""
    orgs = load_organisations() if orgs is None else orgs
    enfants = {}
    for o in orgs:
        enfants.setdefault(o.get("parentId"), []).append(o["id"])
    trouves, a_voir = set(), [org_id]
    while a_voir:
        courant = a_voir.pop()
        if courant in trouves:
            continue
        trouves.add(courant)
        a_voir.extend(enfants.get(courant, []))
    return trouves


def acces_of_teacher(teacher_id, acces=None):
    """Les lignes d'accès actives d'une personne. Plusieurs, c'est le cas normal."""
    acces = load_acces() if acces is None else acces
    return [a for a in acces
            if a.get("teacherId") == teacher_id and a.get("actif", True)]


def portee_orgs(teacher, orgs=None, acces=None):
    """Les organisations qu'une personne voit — ses nœuds et leur descendance.

    C'est la fonction unique d'autorisation prévue à l'étape 2. Elle est écrite
    et éprouvée maintenant, mais **rien ne l'appelle encore** : la brancher
    demande de retirer les deux anciennes fonctions dans le même geste, sans
    quoi les deux règles cohabiteraient et la plus permissive gagnerait.
    """
    if not teacher:
        return set()
    orgs = load_organisations() if orgs is None else orgs
    portee = set()
    for a in acces_of_teacher(teacher["id"], acces):
        portee |= org_subtree_ids(a["orgId"], orgs)
    return portee


def centre_racine(orgs=None):
    """Le premier centre de l'arbre — celui où tout l'existant a été rattaché."""
    centres = orgs_of_type("centre", orgs)
    return centres[0] if centres else None


def centre_de_rattachement(teacher, orgs=None, acces=None):
    """Le centre où poser ce qu'une personne crée.

    Le premier centre de sa portée, sinon le centre d'amorce. Sans cette
    fonction, un groupe créé après l'étape 1 sortirait sans `centreId` et
    l'arbre se mettrait à mentir dès la première rentrée — le genre de
    pourriture qui ne lève aucune erreur et qu'on ne voit qu'au contrôle.
    """
    orgs = load_organisations() if orgs is None else orgs
    for a in acces_of_teacher(teacher["id"], acces) if teacher else []:
        org = find_org(a.get("orgId"), orgs)
        if org and org.get("type") == "centre":
            return org
        for descendant_id in sorted(org_subtree_ids(a["orgId"], orgs)) if org else []:
            d = find_org(descendant_id, orgs)
            if d and d.get("type") == "centre":
                return d
    return centre_racine(orgs)


def poser_acces(teacher_id, org_id, role, accorde_par=None):
    """Ajoute une ligne d'accès si la même n'existe pas déjà. Rend la ligne.

    Idempotente sur le triplet (personne, nœud, rôle) : rejouer un ajout ne
    fabrique pas de doublon, que le contrôle refuserait de toute façon.
    """
    acces = load_acces()
    for a in acces:
        if (a.get("teacherId") == teacher_id and a.get("orgId") == org_id
                and a.get("role") == role):
            if not a.get("actif", True):
                a["actif"] = True
                save_acces(acces)
            return a
    ligne = {
        "id": max((a.get("id", 0) for a in acces), default=0) + 1,
        "teacherId": teacher_id, "orgId": org_id, "role": role, "actif": True,
        "accordePar": accorde_par, "accordeLe": date.today().isoformat(),
    }
    save_acces(acces + [ligne])
    return ligne


def retirer_acces(teacher_id, org_id=None):
    """Éteint les accès d'une personne — à un nœud, ou partout si org_id est None.

    **On éteint, on ne supprime pas**, et on ne touche jamais au compte : une
    personne rattachée à deux centres qui quitte l'un des deux garde l'autre.
    C'est la raison d'être de la table ; une colonne sur le compte aurait
    forcé à choisir entre la couper partout ou nulle part.
    """
    acces = load_acces()
    touches = 0
    for a in acces:
        if a.get("teacherId") != teacher_id or not a.get("actif", True):
            continue
        if org_id is None or a.get("orgId") == org_id:
            a["actif"] = False
            touches += 1
    if touches:
        save_acces(acces)
    return touches


def load_audit():
    return _load_json_list(AUDIT_FILE)


# Le serveur est multi-thread : deux écritures simultanées perdraient une
# ligne. Même raison que le verrou des traductions.
_AUDIT_LOCK = threading.Lock()


def journal(qui, quoi, cible="", details=None):
    """Ajoute une ligne au journal d'audit. N'échoue jamais l'appelant.

    Un journal qui fait planter le geste qu'il enregistre serait pire que pas
    de journal : on perdrait l'action *et* la trace. Il crie dans la sortie
    standard et laisse passer.
    """
    try:
        with _AUDIT_LOCK:
            lignes = load_audit()
            lignes.append({
                "id": max((l.get("id", 0) for l in lignes), default=0) + 1,
                "quand": datetime.now().isoformat(timespec="seconds"),
                "qui": (qui or {}).get("id") if isinstance(qui, dict) else qui,
                "quiNom": (qui or {}).get("nom", "") if isinstance(qui, dict) else "",
                "quoi": quoi,
                "cible": str(cible),
                "details": details or {},
            })
            _save_json(AUDIT_FILE, lignes)
    except Exception as e:
        print(f"[WARN] journal d'audit : {e}", flush=True)


def creer_organisation(type_, parent_id, nom):
    """Crée un CSS ou un centre. Rend (organisation, None) ou (None, motif).

    Les refus sont ici, pas à l'écran : un arbre mal formé ne se répare pas en
    corrigeant l'interface, et le contrôle sortirait en écart de toute façon.
    """
    nom = (nom or "").strip()
    if not nom:
        return None, "Le nom est requis"
    if type_ not in ("css", "centre"):
        return None, "Un réseau ne se crée pas : il n'y en a qu'un"
    orgs = load_organisations()
    parent = find_org(parent_id, orgs)
    if parent is None:
        return None, "Organisation parente introuvable"
    attendu = "reseau" if type_ == "css" else "css"
    if parent.get("type") != attendu:
        libelle = {"reseau": "le réseau", "css": "un CSS"}[attendu]
        return None, f"Un {type_} se place sous {libelle}, pas sous un {parent.get('type')}"
    org = {
        "id": max((o["id"] for o in orgs), default=0) + 1,
        "type": type_, "parentId": parent["id"], "nom": nom[:120],
        "actif": True, "createdAt": date.today().isoformat(),
    }
    save_organisations(orgs + [org])
    return org, None


def valider_acces(teacher_id, org_id, role):
    """Dit si un accès a un sens. Rend None si oui, le motif du refus sinon."""
    if role not in ROLES_ACCES:
        return "Rôle inconnu"
    if role == "fondateur":
        # Le fondateur n'est pas un rôle qu'on distribue : il se déduit du
        # compte du premier démarrage (`founder_id`). En poser un second
        # ferait deux vérités pour une même question.
        return "Le rôle « fondateur » ne s'accorde pas : il appartient au compte du premier démarrage"
    if not any(t["id"] == teacher_id for t in load_teachers()):
        return "Compte introuvable"
    org = find_org(org_id)
    if org is None:
        return "Organisation introuvable"
    attendus = NOEUD_DU_ROLE[role]
    if org.get("type") not in attendus:
        quoi = " ou ".join({"reseau": "le réseau", "css": "un CSS",
                            "centre": "un centre"}[t] for t in attendus)
        return f"Le rôle « {role} » se pose sur {quoi}, pas sur un {org.get('type')}"
    return None


def load_invitations():
    return _load_json_list(INVITATIONS_FILE)


def save_invitations(inv):
    _save_json(INVITATIONS_FILE, inv)


def empreinte_jeton(jeton):
    """Le jeton d'invitation se garde comme un mot de passe : en empreinte.

    Il ouvre la création d'un compte ; le lire dans un fichier reviendrait à
    lire un mot de passe. Pas de PBKDF2 ici — un jeton de 256 bits tiré au
    hasard n'a pas de dictionnaire à lui opposer, un SHA-256 suffit.
    """
    return hashlib.sha256((jeton or "").encode("utf-8")).hexdigest()


def invitation_valide(jeton, invitations=None):
    """Rend l'invitation ouverte correspondant au jeton, ou None.

    La comparaison passe par `hmac.compare_digest` : comparer deux empreintes
    avec `==` laisse fuir leur préfixe commun par le temps de réponse.
    """
    if not jeton:
        return None
    cible = empreinte_jeton(jeton)
    maintenant = datetime.now().isoformat(timespec="seconds")
    for inv in (load_invitations() if invitations is None else invitations):
        if inv.get("utiliseLe"):
            continue
        if inv.get("expire", "") <= maintenant:
            continue
        if hmac.compare_digest(inv.get("empreinte", ""), cible):
            return inv
    return None


def creer_invitation(courriel, role, org_id, nom="", par=None, invitations=None):
    """Prépare une invitation. Rend (invitation, jeton_en_clair) ou (None, motif).

    Le jeton en clair ne repasse jamais : c'est la seule fois qu'on le voit.
    """
    courriel = normalize_email(courriel)
    if not courriel or "@" not in courriel:
        return None, f"Courriel invalide : {courriel or '(vide)'}"
    if any(normalize_email(t.get("courriel")) == courriel for t in load_teachers()):
        return None, f"{courriel} a déjà un compte"
    motif = valider_acces_sans_compte(org_id, role)
    if motif:
        return None, motif
    invitations = load_invitations() if invitations is None else invitations
    if any(i.get("courriel") == courriel and not i.get("utiliseLe")
           and i.get("expire", "") > datetime.now().isoformat(timespec="seconds")
           for i in invitations):
        return None, f"{courriel} a déjà une invitation en cours"
    jeton = uuid.uuid4().hex + uuid.uuid4().hex
    inv = {
        "id": max((i.get("id", 0) for i in invitations), default=0) + 1,
        "courriel": courriel,
        "nom": (nom or "").strip()[:80],
        "role": role,
        "orgId": org_id,
        "empreinte": empreinte_jeton(jeton),
        "creeLe": datetime.now().isoformat(timespec="seconds"),
        "expire": (datetime.now() + timedelta(days=INVITATION_JOURS)).isoformat(timespec="seconds"),
        "utiliseLe": "",
        "creePar": par,
    }
    return inv, jeton


def valider_acces_sans_compte(org_id, role):
    """La moitié de `valider_acces()` qui ne regarde pas le compte.

    Une invitation vise un courriel qui n'a pas encore de compte : on ne peut
    pas vérifier l'existence du compte, mais on doit vérifier que le rôle a un
    sens sur ce nœud — sinon l'invitation créerait un accès que le contrôle
    déclarerait en écart le lendemain.
    """
    if role not in ROLES_ACCES:
        return "Rôle inconnu"
    if role == "fondateur":
        return "Le rôle « fondateur » ne s'accorde pas"
    org = find_org(org_id)
    if org is None:
        return "Organisation introuvable"
    attendus = NOEUD_DU_ROLE[role]
    if org.get("type") not in attendus:
        quoi = " ou ".join({"reseau": "le réseau", "css": "un CSS",
                            "centre": "un centre"}[t] for t in attendus)
        return f"Le rôle « {role} » se pose sur {quoi}, pas sur un {org.get('type')}"
    return None


def invitation_publique(inv):
    """Ce qu'on montre d'une invitation — jamais l'empreinte."""
    org = find_org(inv.get("orgId"))
    return {
        "id": inv.get("id"), "courriel": inv.get("courriel"),
        "nom": inv.get("nom", ""), "role": inv.get("role"),
        "orgId": inv.get("orgId"),
        "organisation": (org or {}).get("nom", ""),
        "creeLe": inv.get("creeLe"), "expire": inv.get("expire"),
        "utiliseLe": inv.get("utiliseLe", ""),
    }


# ── Le relevé quotidien ─────────────────────────────────────────────────────

def load_stats_jour():
    if STATS_JOUR_FILE.exists():
        try:
            with open(STATS_JOUR_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
        except json.JSONDecodeError:
            print("[WARN] stats_jour.json illisible, relevé refait", flush=True)
    return {"jours": {}, "parEnseignant": {}}


def save_stats_jour(data):
    _save_json(STATS_JOUR_FILE, data)


def _minutes_de_seance(horodatages):
    """Somme des séances d'un élève dans une journée, en minutes.

    Une séance se ferme après `STATS_PAUSE_MIN` sans événement. Rien ne mesure
    le temps réel passé dans une activité — le portail élève le dit déjà de
    son estimation — donc ce chiffre est un **plancher**, et les écrans
    doivent l'annoncer comme tel.
    """
    if not horodatages:
        return 0
    marques = sorted(horodatages)
    total, debut, precedent = 0, marques[0], marques[0]
    for t in marques[1:]:
        if (t - precedent) > STATS_PAUSE_MIN * 60:
            total += max((precedent - debut) / 60, STATS_EVENEMENT_MIN)
            debut = t
        precedent = t
    total += max((precedent - debut) / 60, STATS_EVENEMENT_MIN)
    return round(total)


def _horodatage(iso):
    try:
        return datetime.fromisoformat(str(iso)[:19]).timestamp()
    except (ValueError, TypeError):
        return None


def calculer_jour(jour, progres, eleve_vers_centre, eleve_vers_prof):
    """Le relevé d'une journée, à deux grains.

    Deux dictionnaires, et c'est **la** décision de l'étape 4 : `centres` ne
    porte aucun identifiant d'enseignant, `enseignants` en porte. La vue d'un
    CSS ne lit que le premier. Les mélanger remettrait le filtrage à
    l'affichage, où il s'oublie.
    """
    centres, enseignants = {}, {}
    seances = {}   # (clé, studentId) -> [horodatages]

    def sac(table, cle):
        return table.setdefault(cle, {
            "eleves": set(), "evenements": 0, "activitesTerminees": 0,
            "premierCoupOk": 0, "premierCoupTotal": 0, "minutes": 0,
        })

    for e in progres:
        if str(e.get("timestamp", ""))[:10] != jour:
            continue
        sid = e.get("studentId")
        centre = eleve_vers_centre.get(sid)
        if centre is None:
            continue
        prof = eleve_vers_prof.get(sid)
        cles = [("c", centre)] + ([("t", centre, prof)] if prof else [])
        for cle in cles:
            table = centres if cle[0] == "c" else enseignants
            k = str(centre) if cle[0] == "c" else f"{centre}:{prof}"
            d = sac(table, k)
            d["eleves"].add(sid)
            d["evenements"] += 1
            if e.get("event") == "exercise_completed":
                d["activitesTerminees"] += 1
            ft, zones = e.get("firstTry"), e.get("zones")
            if isinstance(ft, int) and isinstance(zones, int) and zones > 0:
                d["premierCoupOk"] += ft
                d["premierCoupTotal"] += zones
            ts = _horodatage(e.get("timestamp"))
            if ts is not None:
                seances.setdefault((k, sid), []).append(ts)

    for (k, _sid), marques in seances.items():
        table = enseignants if ":" in k else centres
        table[k]["minutes"] += _minutes_de_seance(marques)

    for table in (centres, enseignants):
        for d in table.values():
            d["elevesActifs"] = len(d.pop("eleves"))
    return centres, enseignants


def relever_stats(force=False):
    """Met le relevé à jour. Les jours passés ne se recalculent jamais.

    Le journal d'événements est en ajout seulement : une journée close ne
    bouge plus. On ne recalcule donc que le jour courant — c'est ce qui
    permettra à ce relevé de tenir quand `progress.json` fera des millions de
    lignes, et c'est aussi pourquoi il n'a besoin d'aucune tâche de nuit.
    """
    data = load_stats_jour()
    if force:
        data = {"jours": {}, "parEnseignant": {}}
    progres = load_progress()
    groupes = {g["id"]: g for g in load_groups()}
    eleve_vers_centre, eleve_vers_prof = {}, {}
    for el in load_students():
        g = groupes.get(el.get("groupId"))
        if not g:
            continue
        if g.get("centreId"):
            eleve_vers_centre[el["id"]] = g["centreId"]
            eleve_vers_prof[el["id"]] = g.get("teacherId")

    aujourdhui = date.today().isoformat()
    jours = {str(e.get("timestamp", ""))[:10] for e in progres}
    jours = {j for j in jours if len(j) == 10}
    a_faire = [j for j in jours if j not in data["jours"] or j == aujourdhui]
    for j in sorted(a_faire):
        centres, enseignants = calculer_jour(j, progres, eleve_vers_centre,
                                             eleve_vers_prof)
        data["jours"][j] = centres
        data["parEnseignant"][j] = enseignants
    if a_faire:
        data["calculeLe"] = datetime.now().isoformat(timespec="seconds")
        save_stats_jour(data)
    return data


def a_role_sur(teacher, org_id, roles, exact=False):
    """La personne a-t-elle l'un de ces rôles sur ce nœud ?

    `exact=True` exige que l'accès soit posé **sur ce nœud précis**, sans
    remonter la chaîne. C'est ce qui tient la décision du 25 août 2026 : un
    gestionnaire de CSS voit ses centres, jamais leurs enseignants. Sa ligne
    d'accès est sur le CSS ; la vue par enseignant demande un accès posé sur
    le centre lui-même.
    """
    if not teacher:
        return False
    if is_founder(teacher):
        return True
    orgs = load_organisations()
    chaine = {o["id"] for o in org_chain(org_id, orgs)} if not exact else {org_id}
    for a in acces_of_teacher(teacher["id"]):
        if a.get("role") in roles and a.get("orgId") in chaine:
            return True
    return False


def arbre_pour_lecture():
    """L'arbre, les accès et les groupes, en une réponse lisible à l'œil.

    Sert la vérification, pas une interface : tant qu'il n'y a pas d'écran, il
    faut bien un endroit où regarder ce que la migration a posé.
    """
    orgs = load_organisations()
    acces = load_acces()
    groups = load_groups()
    teachers = {t["id"]: t for t in load_teachers()}
    par_centre = {}
    for g in groups:
        par_centre.setdefault(g.get("centreId"), []).append(
            {"id": g["id"], "nom": g.get("nom", ""), "titulaire": g.get("teacherId")})
    return {
        "organisations": [
            {**o,
             "ia": o.get("ia", "herite"),
             # L'état effectif est calculé ici, pas dans la page : l'héritage
             # est une règle du serveur, et deux calculs de la même règle
             # finissent toujours par diverger.
             "iaEffective": ("autorisee" if ia_effective(o["id"], orgs)[0]
                             else "interdite"),
             "iaDecidePar": (ia_effective(o["id"], orgs)[1] or {}).get("nom", ""),
             "enfants": sorted(x["id"] for x in orgs if x.get("parentId") == o["id"]),
             "groupes": par_centre.get(o["id"], [])}
            for o in orgs
        ],
        "acces": [
            {**a,
             "nom": teachers.get(a.get("teacherId"), {}).get("nom", "compte inconnu"),
             "organisation": (find_org(a.get("orgId"), orgs) or {}).get("nom", "")}
            for a in acces
        ],
        "orphelins": {
            "groupesSansCentre": [g["id"] for g in groups if not g.get("centreId")],
            "comptesSansAcces": sorted(
                set(teachers) - {a.get("teacherId") for a in acces}),
        },
    }


def groupes_de_portee(teacher, orgs=None, acces=None):
    """Les groupes visibles d'une personne, selon l'arbre. Pas encore en service.

    Un groupe appartient à un **centre** ; le `teacherId` du groupe ne dit plus
    que qui en est titulaire. Une personne rattachée à deux centres voit les
    groupes des deux, et le nom du centre doit être écrit à côté du groupe —
    deux « Niveau 4 » dans deux centres est une certitude, pas une hypothèse.

    **Le rôle « prof » est le seul qui ne voit pas tout son sous-arbre.** Son
    accès dit *où il enseigne*, pas *ce qu'il voit* : sans cette exception, un
    enseignant rattaché à un centre verrait les groupes de tous ses collègues,
    et l'ouverture à un deuxième centre commencerait par élargir les droits de
    tout le monde à l'intérieur du premier. Le défaut a été trouvé au bac
    d'essai de l'étape 1 — deux groupes dans un même centre, et le second
    enseignant les voyait tous les deux.
    """
    if not teacher:
        return []
    orgs = load_organisations() if orgs is None else orgs
    lignes = acces_of_teacher(teacher["id"], acces)
    large, restreint = set(), set()
    for a in lignes:
        cible = restreint if a.get("role") == "prof" else large
        cible |= org_subtree_ids(a["orgId"], orgs)
    return [
        g for g in load_groups()
        if g.get("centreId") in large
        or (g.get("centreId") in restreint and est_enseignant_du_groupe(teacher, g))
    ]


def est_enseignant_du_groupe(teacher, group):
    """Titulaire ou co-enseignant. Le champ `coEnseignants` n'existe pas encore
    dans les groupes ; il est lu dès maintenant pour que l'ajouter plus tard ne
    demande pas de repasser ici."""
    if group.get("teacherId") == teacher["id"]:
        return True
    return teacher["id"] in (group.get("coEnseignants") or [])


# ── Mots de passe et sessions enseignants ───────────────────────────────────

def hash_password(password, salt=None, iterations=200_000):
    salt = salt or uuid.uuid4().hex
    dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), iterations)
    return f"pbkdf2_sha256${iterations}${salt}${dk.hex()}"


def verify_password(password, stored):
    try:
        algo, iterations, salt, digest = stored.split("$")
    except (ValueError, AttributeError):
        return False
    if algo != "pbkdf2_sha256":
        return False
    dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), int(iterations))
    return hmac.compare_digest(dk.hex(), digest)


def load_sessions():
    """Les sessions enseignantes. Un **dictionnaire**, pas une liste.

    Elle lisait le fichier en direct, ce qui a suffi à casser toute
    l'authentification dès que `save_sessions` a commencé à écrire en base :
    les jetons partaient dans Postgres et on les cherchait sur le disque.
    Trouvé en jouant la migration, pas en la relisant — le serveur démarrait
    parfaitement et répondait 401 à tout le monde.
    """
    return _load_json_doc(SESSIONS_FILE, {})


def save_sessions(sessions):
    _save_json(SESSIONS_FILE, sessions)


def create_session(teacher_id):
    sessions = load_sessions()
    now = datetime.now()
    # Purge des jetons expirés à chaque connexion : pas de tâche de fond à gérer.
    sessions = {
        t: s for t, s in sessions.items()
        if s.get("expiresAt", "") > now.isoformat(timespec="seconds")
    }
    token = uuid.uuid4().hex + uuid.uuid4().hex
    sessions[token] = {
        "teacherId": teacher_id,
        "createdAt": now.isoformat(timespec="seconds"),
        "expiresAt": (now + timedelta(days=SESSION_DAYS)).isoformat(timespec="seconds"),
    }
    save_sessions(sessions)
    return token


def destroy_session(token):
    sessions = load_sessions()
    if token in sessions:
        del sessions[token]
        save_sessions(sessions)


def teacher_from_token(token):
    if not token:
        return None
    session = load_sessions().get(token)
    if not session:
        return None
    if session.get("expiresAt", "") <= datetime.now().isoformat(timespec="seconds"):
        destroy_session(token)
        return None
    return next((t for t in load_teachers() if t["id"] == session["teacherId"]), None)


def founder_id(teachers=None):
    """L'identifiant du compte fondateur.

    Le fondateur est le compte du premier démarrage — celui que crée
    `/api/prof/setup` ou l'amorce par variables d'environnement. Les deux
    chemins lui donnent l'`id` 1 ; on prend malgré tout le plus petit `id`
    présent, pour ne pas dépendre d'un nombre écrit en dur.

    `PROF_FONDATEUR` (un courriel) permet de désigner un autre compte sans
    toucher au code — utile si le compte du premier démarrage n'est pas celui
    de la personne qui tient l'installation.
    """
    teachers = load_teachers() if teachers is None else teachers
    if not teachers:
        return None
    voulu = normalize_email(os.environ.get("PROF_FONDATEUR", ""))
    if voulu:
        for t in teachers:
            if normalize_email(t.get("courriel")) == voulu:
                return t["id"]
    return min(t["id"] for t in teachers)


def is_founder(teacher, teachers=None):
    """Seul le fondateur ouvre des comptes « administrateur ».

    Un administrateur ordinaire gère les enseignants et leurs groupes ; il ne
    fabrique pas ses pairs, et ne peut pas non plus s'emparer du compte
    fondateur en lui réinitialisant son mot de passe.
    """
    return bool(teacher) and teacher.get("id") == founder_id(teachers)


def public_teacher(teacher, teachers=None):
    """Vue d'un enseignant sans son empreinte de mot de passe."""
    return {
        "id": teacher["id"],
        "nom": teacher.get("nom", ""),
        "courriel": teacher.get("courriel", ""),
        "role": teacher.get("role", "prof"),
        "createdAt": teacher.get("createdAt", ""),
        "fondateur": is_founder(teacher, teachers),
    }


def normalize_email(value):
    return (value or "").strip().lower()


def normalize_lien(value):
    """Un lien de rencontre est une URL http(s) ou rien. Refuser le reste évite
    qu'un « javascript: » se retrouve dans le portail des élèves."""
    lien = (value or "").strip()
    if not lien:
        return ""
    return lien[:500] if lien.lower().startswith(("http://", "https://")) else ""


# ── Migration vers le multi-groupes ─────────────────────────────────────────

def migrate_multi_groupes():
    """Fait passer une installation mono-groupe au modèle enseignants/groupes.

    Idempotent : ne fait rien si les fichiers existent déjà. Les dates
    actuellement portées par les activités deviennent la planification du
    groupe historique, et les élèves existants y sont rattachés.
    """
    groups = load_groups()
    if not groups:
        groups = [{
            "id": 1,
            "nom": "Niveau 4",
            "teacherId": None,
            "createdAt": date.today().isoformat(),
        }]
        save_groups(groups)
        print("[migration] Groupe historique « Niveau 4 » créé", flush=True)

    default_group_id = groups[0]["id"]

    # Dates portées par les activités → planification du groupe historique.
    #
    # Avant le multi-groupes, une activité sans date était visible de tous les
    # élèves ; désormais il faut une date de disponibilité (un groupe neuf part
    # vide). Pour ne rien retirer à la classe en cours, on ouvre explicitement
    # au groupe historique tout ce qui lui était déjà visible : sa date prévue
    # si elle existe, sinon la date où l'activité a été vue, sinon aujourd'hui.
    if not SCHEDULE_FILE.exists():
        today_str = date.today().isoformat()
        entries = []
        for a in load_activities():
            date_fin = a.get("dateFin", "")
            date_vue = a.get("dateVue", "")
            entries.append({
                "groupId": default_group_id,
                "activityId": a["id"],
                "dateVue": date_vue,
                "datePrevue": a.get("datePrevue", "") or date_vue or today_str,
                "dateFin": date_fin,
            })
        save_schedule(entries)
        print(f"[migration] {len(entries)} activités ouvertes au groupe {default_group_id} "
              "(état d'avant le multi-groupes conservé)", flush=True)

    # Élèves sans groupe → groupe historique
    students = load_students()
    orphans = [s for s in students if not s.get("groupId")]
    if orphans:
        for s in orphans:
            s["groupId"] = default_group_id
        save_students(students)
        print(f"[migration] {len(orphans)} élèves rattachés au groupe {default_group_id}", flush=True)

    # Premier administrateur : semé par variables d'environnement si fournies,
    # sinon créé par l'écran d'installation au premier lancement.
    teachers = load_teachers()
    if not teachers:
        email = normalize_email(os.environ.get("PROF_COURRIEL", ""))
        password = os.environ.get("PROF_MOTDEPASSE", "")
        if email and password:
            teachers = [{
                "id": 1,
                "nom": os.environ.get("PROF_NOM", "Enseignant"),
                "courriel": email,
                "motDePasse": hash_password(password),
                "role": "admin",
                "createdAt": date.today().isoformat(),
            }]
            save_teachers(teachers)
            print(f"[migration] Compte administrateur créé pour {email}", flush=True)
        else:
            print("[migration] Aucun enseignant — l'écran d'installation "
                  "(/prof.html) créera le premier compte", flush=True)

    # Le groupe historique appartient au premier enseignant connu
    teachers = load_teachers()
    if teachers:
        groups = load_groups()
        changed = False
        for g in groups:
            if not g.get("teacherId"):
                g["teacherId"] = teachers[0]["id"]
                changed = True
        if changed:
            save_groups(groups)


def migrate_organisations():
    """Pose l'arbre des organisations sur une installation à un seul centre.

    Idempotente, et **sans effet visible** : aucune page ne change, aucun élève
    ne voit de différence, aucune autorisation ne passe encore par l'arbre.
    Elle se contente de dire de qui relève ce qui existe déjà — un réseau, un
    CSS, un centre — pour que l'étape 2 n'ait plus qu'à brancher la portée.

    Trois écritures, chacune gardée par sa propre condition : on ne réécrit
    jamais un rattachement posé à la main, et un fichier déjà peuplé est laissé
    tel quel.
    """
    orgs = load_organisations()

    # 1. L'arbre d'amorce. Les noms se règlent par variables d'environnement
    #    pour qu'une installation chez un partenaire n'hérite pas des nôtres.
    if not orgs:
        aujourdhui = date.today().isoformat()
        orgs = [
            {"id": 1, "type": "reseau", "parentId": None,
             "nom": os.environ.get("RESEAU_NOM", "francis"),
             "actif": True, "createdAt": aujourdhui},
            {"id": 2, "type": "css", "parentId": 1,
             "nom": os.environ.get("CSS_NOM", "Centre de services scolaire"),
             "actif": True, "createdAt": aujourdhui},
            {"id": 3, "type": "centre", "parentId": 2,
             "nom": os.environ.get("CENTRE_NOM", "Centre de francisation"),
             "actif": True, "createdAt": aujourdhui},
        ]
        save_organisations(orgs)
        print("[migration] Arbre d'amorce créé : réseau → CSS → centre", flush=True)

    centre = centre_racine(orgs)
    if centre is None:
        print("[WARN] migrate_organisations : aucun centre dans l'arbre, "
              "rattachements laissés en l'état", flush=True)
        return

    # 2. Les groupes existants entrent dans le centre d'amorce. Le `teacherId`
    #    reste : il ne dit plus la propriété, il dit qui est titulaire.
    groups = load_groups()
    sans_centre = [g for g in groups if not g.get("centreId")]
    if sans_centre:
        for g in sans_centre:
            g["centreId"] = centre["id"]
        save_groups(groups)
        print(f"[migration] {len(sans_centre)} groupes rattachés au centre "
              f"{centre['id']} « {centre['nom']} »", flush=True)

    # 3. Une ligne d'accès par personne qui n'en a aucune. Le rôle est déduit
    #    de l'ancien champ `role`, et le fondateur se pose sur le réseau — pas
    #    sur le centre, sans quoi il ne verrait pas les CSS à venir.
    teachers = load_teachers()
    acces = load_acces()
    deja = {a.get("teacherId") for a in acces}
    fondateur = founder_id(teachers)
    reseaux = orgs_of_type("reseau", orgs)
    racine = reseaux[0] if reseaux else centre
    prochain = max([a.get("id", 0) for a in acces], default=0) + 1
    ajouts = []
    for t in teachers:
        if t["id"] in deja:
            continue
        if t["id"] == fondateur:
            role, org = "fondateur", racine
        elif t.get("role") == "admin":
            role, org = "direction", centre
        else:
            role, org = "prof", centre
        ajouts.append({
            "id": prochain, "teacherId": t["id"], "orgId": org["id"],
            "role": role, "actif": True,
            "accordePar": fondateur, "accordeLe": date.today().isoformat(),
        })
        prochain += 1
    if ajouts:
        save_acces(acces + ajouts)
        resume = ", ".join(f"{a['role']}→{a['orgId']}" for a in ajouts)
        print(f"[migration] {len(ajouts)} accès posés ({resume})", flush=True)


def load_vocab_progress():
    return _load_json_list(VOCAB_PROGRESS_FILE)


def save_vocab_progress(data):
    _save_json(VOCAB_PROGRESS_FILE, data)


# Le serveur est multi-thread : deux élèves peuvent demander une traduction en
# même temps. Sans verrou, la deuxième écriture écraserait la première.
_VOCAB_TR_LOCK = threading.Lock()


def translation_key(langue, mot, definition):
    """Clé de cache. La définition entre dans la clé (par son empreinte) parce
    que deux modules peuvent définir le même mot différemment : sans elle, la
    traduction du module 9 s'afficherait sous la définition du module 6."""
    empreinte = hashlib.sha1(definition.strip().encode("utf-8")).hexdigest()[:10]
    return "%s|%s|%s" % (langue.strip().lower(), mot.strip().lower(), empreinte)


def load_translations():
    """Le cache des traductions — un dictionnaire, comme les sessions."""
    return _load_json_doc(VOCAB_TRANSLATIONS_FILE, {})


def save_translation(key, value):
    with _VOCAB_TR_LOCK:
        cache = load_translations()
        cache[key] = value
        _save_json(VOCAB_TRANSLATIONS_FILE, cache)


_OUTILS_LOCK = threading.Lock()
# Sérialise le seul moment où deux requêtes se marcheraient dessus : l'élagage.
# Lire et écrire un MP3 ne se verrouille pas — chaque fichier a son propre nom.
_VOIX_CACHE_LOCK = threading.Lock()


def outils_key(genre, langue, texte):
    """Clé de cache d'un passage. Le genre entre dans la clé : la traduction et
    la reformulation d'une même phrase sont deux résultats différents."""
    empreinte = hashlib.sha1(" ".join(texte.split()).encode("utf-8")).hexdigest()[:16]
    return "%s|%s|%s" % (genre, (langue or "").strip().lower(), empreinte)


def load_outils_cache():
    if OUTILS_CACHE_FILE.exists():
        try:
            with open(OUTILS_CACHE_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
        except (json.JSONDecodeError, OSError):
            return {}
    return {}


def save_outils_entry(key, value):
    with _OUTILS_LOCK:
        cache = load_outils_cache()
        cache[key] = value
        OUTILS_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
        with open(OUTILS_CACHE_FILE, "w", encoding="utf-8") as f:
            json.dump(cache, f, ensure_ascii=False, indent=2)


class _VoixIndisponible(Exception):
    """La synthèse a échoué. `http` porte le code quand il y en a un."""

    def __init__(self, message, http=None):
        super().__init__(message)
        self.http = http


def _synthese_azure(role, texte):
    """Un extrait de parole, par Azure Speech. Renvoie du MP3 brut.

    Le SSML est bâti par `build/azure_voix.py` et non recopié ici : c'est là
    que vivent la table des rôles, le taux global du cours et la hauteur qui
    distingue les deux voix féminines. Deux constructions séparées finiraient
    par diverger, et l'élève entendrait au jeu de rôle une voix qui ne serait
    plus celle de ses dialogues.

    En production, la ressource Azure demande **deux** variables : la clé et
    la région. Une clé juste avec la mauvaise région rend un 401 dont le
    message ne dit pas que c'est la cause — d'où le rappel dans l'erreur.
    """
    cle = os.environ.get("AZURE_SPEECH_KEY", "").strip()
    region = os.environ.get("AZURE_SPEECH_REGION", "").strip() or "canadacentral"
    if not cle:
        raise _VoixIndisponible("AZURE_SPEECH_KEY absente de l'environnement")

    sys.path.insert(0, str(BASE_DIR / "build"))
    from azure_voix import ssml as _ssml            # noqa: E402

    req = urllib.request.Request(
        f"https://{region}.tts.speech.microsoft.com/cognitiveservices/v1",
        data=_ssml(texte, role).encode("utf-8"),
        headers={
            "Ocp-Apim-Subscription-Key": cle,
            "Content-Type": "application/ssml+xml",
            "X-Microsoft-OutputFormat": "audio-24khz-160kbitrate-mono-mp3",
            "User-Agent": "francisation",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=25) as resp:
            return resp.read()
    except urllib.error.HTTPError as e:
        detail = e.read().decode("utf-8", errors="replace")[:200]
        indice = (f" — la région « {region} » ne correspond peut-être pas à la "
                  "ressource") if e.code == 401 else ""
        raise _VoixIndisponible(f"HTTP {e.code}{indice} {detail}", e.code)
    except (urllib.error.URLError, TimeoutError) as e:
        raise _VoixIndisponible(f"injoignable : {e}")


def voix_cache_chemin(voix, texte):
    """Fichier où dort le MP3 d'un texte dit par une voix. La voix entre dans
    la clé : la même réplique lue par la propriétaire et par le visiteur sont
    deux enregistrements. Espaces normalisés, comme pour outils_key()."""
    empreinte = hashlib.sha1(" ".join(texte.split()).encode("utf-8")).hexdigest()[:20]
    return VOIX_CACHE_DIR / ("%s-%s.mp3" % (voix, empreinte))


def voix_cache_lire(chemin):
    """Rend les octets du MP3, ou None. Touche le fichier au passage : c'est la
    date de dernier service qui décide de ce que l'élagage garde."""
    try:
        audio = chemin.read_bytes()
    except OSError:
        return None
    if not audio:
        return None
    try:
        os.utime(chemin, None)
    except OSError:
        pass          # cache en lecture seule : on sert quand même
    return audio


def voix_cache_ecrire(chemin, audio):
    """Range un MP3. Écriture par fichier temporaire puis renommage : un élève
    qui recharge pendant l'écriture ne doit jamais lire un MP3 tronqué."""
    try:
        VOIX_CACHE_DIR.mkdir(parents=True, exist_ok=True)
        provisoire = chemin.with_suffix(".mp3.part-%s" % uuid.uuid4().hex[:8])
        provisoire.write_bytes(audio)
        provisoire.replace(chemin)
    except OSError as e:
        print(f"[WARN] cache voix non écrit : {e}", flush=True)
        return
    _voix_cache_elaguer()


def _voix_cache_elaguer():
    """Ramène le cache sous son plafond en retirant les fichiers les moins
    récemment servis. Le cache n'est jamais une source de vérité : tout ce
    qu'on jette sera régénéré au prochain appel."""
    with _VOIX_CACHE_LOCK:
        try:
            fichiers = [(f.stat().st_mtime, f.stat().st_size, f)
                        for f in VOIX_CACHE_DIR.glob("*.mp3")]
        except OSError:
            return
        total = sum(taille for _, taille, _ in fichiers)
        if total <= VOIX_CACHE_MAX_OCTETS:
            return
        cible = int(VOIX_CACHE_MAX_OCTETS * 0.8)
        for _, taille, f in sorted(fichiers):
            if total <= cible:
                break
            try:
                f.unlink()
                total -= taille
            except OSError:
                pass
        print(f"[voix] cache élagué à {total / (1024 * 1024):.1f} Mo", flush=True)


def log_translation_report(entry):
    with _VOCAB_TR_LOCK:
        journal = []
        if VOCAB_REPORTS_FILE.exists():
            try:
                with open(VOCAB_REPORTS_FILE, "r", encoding="utf-8") as f:
                    journal = json.load(f)
            except (json.JSONDecodeError, OSError):
                journal = []
        journal.append(entry)
        VOCAB_REPORTS_FILE.parent.mkdir(parents=True, exist_ok=True)
        with open(VOCAB_REPORTS_FILE, "w", encoding="utf-8") as f:
            json.dump(journal, f, ensure_ascii=False, indent=2)


